mapper.select:
SELECT MENU_CD, PARENT_MENU_CD, MENU_DEPTH, MENU_NM, ORIGINAL_MENU_NM, SORT_SEQ, USE_YN, DEL_YN, REG_DT, RGTR_NM, MDFCN_DT, MDFR_NM FROM HMPG_MENU WHERE DEL_YN = 'N' AND MENU_DEPTH = #{menuDepth}
AND PARENT_MENU_CD = #{parentMenuCd}
AND (PARENT_MENU_CD IS NULL OR PARENT_MENU_CD = '')
ORDER BY SORT_SEQ, MENU_CD

mapper.update:
UPDATE HMPG_MENU
SET SORT_SEQ = #{sortSeq},
	MDFCN_DT = NOW(),
	MDFR_NM = #{mdtr}
WHERE MENU_CD = #{menuCd}
	AND DEL_YN = 'N'
